styles.css:
.vds-test-neon-marker {
  color: #073642;
  font-weight: 800;
  padding: 0.08em 0.28em;
  border-radius: 0.25em;
  background: linear-gradient(100deg, #72f1d5, #79c7ff);
  box-shadow: 0 0.08em 0.35em rgba(38, 198, 218, 0.35);
}

.vds-test-coral-note {
  position: relative;
  margin: 1.2em 0;
  padding: 1em 1.25em 1em 1.5em;
  border: 2px solid #ff7f6e;
  border-left-width: 0.5em;
  border-radius: 0.65em;
  color: #612d2a;
  background: linear-gradient(135deg, #fff3ef, #ffe4dc);
  box-shadow: 0 0.4em 1.2em rgba(180, 75, 58, 0.16);
}
.vds-test-coral-note::before {
  content: "TEST";
  display: inline-block;
  margin-right: 0.75em;
  color: #b64035;
  font: 800 0.7em/1.4 system-ui, sans-serif;
  letter-spacing: 0.12em;
}

.vds-test-violet-heading {
  margin: 1.4em 0 0.75em;
  padding-bottom: 0.35em;
  color: #6f42c1;
  border-bottom: 3px solid #b794f4;
  text-shadow: 0 0.08em 0.22em rgba(111, 66, 193, 0.2);
  letter-spacing: 0.06em;
}
.vds-test-violet-heading::after {
  content: "";
  display: block;
  width: 4em;
  height: 0.16em;
  margin-top: 0.35em;
  border-radius: 999px;
  background: linear-gradient(90deg, #6f42c1, #e879f9);
}
